mapper.select:
SELECT COUNT(*) AS c, COALESCE(SUM(pcount),0) AS p
FROM sh_survey_object
WHERE wscd = #{wscd}

SELECT wsnm AS "流域全称", COALESCE(NULLIF(TRIM(alias_name),''), wsnm) AS "流域名称", wscd AS "流域编码", river_name AS "所在水系", wsarea AS "流域面积km2", village_count AS "防治村个数", gully_count AS "山洪沟道条数" FROM sh_map_watershed
wsnm LIKE '%' || #{keyword} || '%' OR alias_name LIKE '%' || #{keyword} || '%' OR wscd = #{keyword}
ORDER BY wsnm LIMIT 50

SELECT wscd, wsnm, alias_name
FROM sh_map_watershed
WHERE wscd = #{key} OR wsnm = #{key} OR alias_name = #{key}

SELECT wscd, wsnm, alias_name
FROM sh_map_watershed
WHERE wsnm LIKE #{fullKey} OR alias_name LIKE #{shortKey} OR wsnm LIKE #{shortKey}

SELECT DISTINCT wscd, wsnm, alias_name FROM sh_map_watershed
wscd IN #{c}
ORDER BY wscd
